#![allow(unused_imports)]
use vstd::prelude::*;

verus! {

fn max_of_list(lst: Vec<i32>) -> (result: i32)
    requires
        lst.len() > 0,
    ensures
        // result is an element of the array
        exists|i: int| 0 <= i < lst.len() && result == lst[i],
        // result is >= every element
        forall|j: int| 0 <= j < lst.len() ==> lst[j] <= result,
{
    let mut m: i32 = lst[0];
    let mut k: usize = 1;

    while k < lst.len()
        invariant
            1 <= k <= lst.len(),
            // m is an element among lst[0..k)
            exists|i: int| 0 <= i < k && m == lst[i],
            // m is >= all elements among lst[0..k)
            forall|j: int| 0 <= j < k ==> lst[j] <= m,
        decreases
            lst.len() - k,
    {
        let x = lst[k];
        if x > m {
            m = x;
        }
        k += 1;
    }

    // After the loop, k == len, so invariants cover the whole array.
    assert(k == lst.len());
    m
}

} // verus!